from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    children: list[dict[str, int]] = [{}]
    bad: list[bool] = [False]

    for word in banned:
        curr = 0
        for ch in word:
            nxt = children[curr].get(ch)
            if nxt is None:
                nxt = len(children)
                children[curr][ch] = nxt
                children.append({})
                bad.append(False)
            curr = nxt
        bad[curr] = True

    num_states = len(children)
    fail = [0] * num_states
    goto: list[dict[str, int]] = [{} for _ in range(num_states)]
    q: deque[int] = deque()

    for ch in alphabet:
        nxt = children[0].get(ch)
        if nxt is not None:
            fail[nxt] = 0
            goto[0][ch] = nxt
            q.append(nxt)
        else:
            goto[0][ch] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for ch in alphabet:
            v = children[u].get(ch)
            if v is not None:
                fail[v] = goto[fail[u]][ch]
                goto[u][ch] = v
                q.append(v)
            else:
                goto[u][ch] = goto[fail[u]][ch]

    state_to_idx = {}
    for u in range(num_states):
        if not bad[u]:
            state_to_idx[u] = len(state_to_idx)

    k = len(state_to_idx)
    mat = [[0] * k for _ in range(k)]
    for u, i in state_to_idx.items():
        row = mat[i]
        for ch in alphabet:
            v = goto[u][ch]
            j = state_to_idx.get(v)
            if j is not None:
                row[j] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * k for _ in range(k)]
        for i in range(k):
            ai = a[i]
            ri = res[i]
            for mid in range(k):
                aik = ai[mid]
                if aik:
                    bmid = b[mid]
                    for j in range(k):
                        ri[j] = (ri[j] + aik * bmid[j]) % MOD
        return res

    def vec_mat_mul(v: list[int], m: list[list[int]]) -> list[int]:
        res = [0] * k
        for i in range(k):
            vi = v[i]
            if vi:
                mi = m[i]
                for j in range(k):
                    res[j] = (res[j] + vi * mi[j]) % MOD
        return res

    vec = [0] * k
    vec[0] = 1
    while n > 0:
        if n & 1:
            vec = vec_mat_mul(vec, mat)
        n >>= 1
        if n > 0:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
